import {useCallback,useEffect,useState} from 'react';
import {Activity,CheckCircle2,Clock3,GitBranch,Play,Plus,RefreshCw,ShieldCheck,Workflow,XCircle} from 'lucide-react';
import {createAutomation,decideAutomationAction,dryRunAutomation,listAutomationHistory,listAutomations,listAutomationTemplates,listPendingAutomationActions,setAutomationEnabled} from '../../lib/practiceOperationsApi';

const TRIGGERS=['CLIENT_CREATED','ONBOARDING_COMPLETED','ASSESSMENT_COMPLETED','SESSION_COMPLETED','APPOINTMENT_CREATED','APPOINTMENT_RESCHEDULED','APPOINTMENT_CANCELLED','NO_SHOW','TASK_OVERDUE','HOMEWORK_COMPLETED','HOMEWORK_OVERDUE','GOAL_DUE','PLAN_PUBLISHED','PLAN_REVIEW_DUE','PACKAGE_ENDING_SOON','SESSIONS_LOW','RENEWAL_DUE','INVOICE_ISSUED','INVOICE_OVERDUE','PAYMENT_RECORDED','CLIENT_INACTIVE','FOLLOWUP_COMPLETED'];
const ACTIONS=['CREATE_TASK','CREATE_FOLLOWUP','ASSIGN_ASSESSMENT','PREPARE_MESSAGE','CREATE_PLAN_REVIEW','CREATE_RENEWAL_TASK','CREATE_INVOICE_REMINDER','CREATE_HOMEWORK_REVIEW','ADD_WAITLIST_ACTION','CREATE_APPOINTMENT_REMINDER','CREATE_RESOURCE_ASSIGNMENT','CREATE_CLIENT_CHECKIN'];
const FIELDS=['CLIENT.status','APPOINTMENT.status','PACKAGE.sessions_remaining','INVOICE.balance_due','HOMEWORK.status','GOAL.status','profession_code','client_id'];
const human=value=>value?.replaceAll('_',' ').toLowerCase().replace(/^./,letter=>letter.toUpperCase());
const blank={name:'',description:'',trigger_type:'SESSION_COMPLETED',requires_confirmation:false,max_retries:3,cooldown_minutes:'',conditions:[],actions:[{action_type:'CREATE_FOLLOWUP',configuration:{delay_days:7},confirmation_required:false}]};

export function ExternalAutomations(){
  const [tab,setTab]=useState('Active'),[items,setItems]=useState([]),[templates,setTemplates]=useState([]),[history,setHistory]=useState([]),[pending,setPending]=useState([]),[state,setState]=useState('loading'),[error,setError]=useState(''),[builder,setBuilder]=useState(false),[form,setForm]=useState(blank),[preview,setPreview]=useState(null);
  const load=useCallback(async()=>{setState('loading');setError('');const results=await Promise.allSettled([listAutomations(),listAutomationTemplates(),listAutomationHistory(),listPendingAutomationActions()]);if(results[0].status==='rejected'){setState('error');setError(results[0].reason?.message||'Automations could not be loaded.');return;}setItems(results[0].value?.items||[]);setTemplates(results[1].status==='fulfilled'?results[1].value?.items||[]:[]);setHistory(results[2].status==='fulfilled'?results[2].value?.items||[]:[]);setPending(results[3].status==='fulfilled'?results[3].value?.items||[]:[]);setState('ready')},[]);
  useEffect(()=>{load()},[load]);
  const save=async()=>{setError('');try{await createAutomation({...form,cooldown_minutes:form.cooldown_minutes?Number(form.cooldown_minutes):null});setBuilder(false);setForm({...blank,actions:[...blank.actions]});await load()}catch(reason){setError(reason.message)}};
  const dryRun=async item=>{setError('');try{setPreview(await dryRunAutomation(item.id,{event_type:item.trigger_type,sample_payload:{client_id:'sample-client',profession_code:'PHYSIOTHERAPIST',CLIENT:{status:'ACTIVE'}}}))}catch(reason){setError(reason.message)}};
  const tabs=['Active','Draft','Disabled','Templates','Execution History','Confirmation Queue'];
  const visible=items.filter(item=>tab==='Active'?item.enabled:tab==='Disabled'?!item.enabled:tab==='Draft'?item.status==='DRAFT':true);
  if(state==='loading')return <StateCard icon={RefreshCw} title="Loading automations" copy="Reading governed workflow definitions and execution history." spin/>;
  if(state==='error')return <StateCard icon={XCircle} title="Automations unavailable" copy={`${error} No empty state is shown because the authoritative request failed.`} action={load}/>;
  return <div className="space-y-6">
    <section className="flex flex-col gap-4 rounded-3xl bg-gradient-to-br from-slate-950 to-blue-900 p-6 text-white sm:flex-row sm:items-end sm:justify-between"><div><p className="text-xs font-bold uppercase tracking-[.2em] text-blue-200">Practice operations</p><h2 className="mt-2 text-3xl font-bold">Workflow automations</h2><p className="mt-2 max-w-2xl text-sm text-blue-100">Build deterministic When → If → Then workflows. External messages, payments and clinical decisions never run autonomously.</p></div><button onClick={()=>setBuilder(true)} className="min-h-11 rounded-xl bg-white px-4 font-bold text-slate-950"><Plus className="mr-2 inline" size={18}/>New automation</button></section>
    {error&&<p role="alert" className="rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-800">{error}</p>}
    <nav aria-label="Automation views" className="flex gap-2 overflow-x-auto pb-1">{tabs.map(value=><button key={value} onClick={()=>setTab(value)} className={`min-h-11 shrink-0 rounded-xl px-4 text-sm font-bold ${tab===value?'bg-slate-950 text-white':'border bg-white text-slate-600'}`}>{value}{value==='Confirmation Queue'&&pending.length?` (${pending.length})`:''}</button>)}</nav>
    {tab==='Templates'?<CardGrid>{templates.map(item=><AutomationCard key={item.name} title={item.name} subtitle={`When ${human(item.trigger_type)}`} detail={item.actions.map(human).join(' + ')}/>)}</CardGrid>:tab==='Execution History'?<History items={history}/>:tab==='Confirmation Queue'?<Confirmation items={pending} decide={async(id,decision)=>{await decideAutomationAction(id,decision);await load()}}/>:<CardGrid>{visible.map(item=><article key={item.id} className="rounded-2xl border bg-white p-5 shadow-sm"><div className="flex items-start justify-between gap-3"><span className="grid h-11 w-11 place-items-center rounded-xl bg-blue-50 text-blue-700"><Workflow/></span><span className={`rounded-full px-3 py-1 text-xs font-bold ${item.enabled?'bg-emerald-50 text-emerald-700':'bg-slate-100 text-slate-600'}`}>{item.enabled?'Active':item.status||'Disabled'}</span></div><h3 className="mt-4 text-lg font-bold">{item.name}</h3><p className="mt-1 text-sm text-slate-500">When {human(item.trigger_type)}</p><div className="mt-5 flex flex-wrap gap-2"><button onClick={()=>dryRun(item)} className="min-h-11 rounded-xl border px-3 text-sm font-bold"><Play size={15} className="mr-1 inline"/>Test</button><button onClick={async()=>{await setAutomationEnabled(item.id,!item.enabled);await load()}} className="min-h-11 rounded-xl bg-slate-950 px-3 text-sm font-bold text-white">{item.enabled?'Disable':'Enable'}</button></div></article>)}{!visible.length&&<Empty label={`No ${tab.toLowerCase()} automations`}/>}</CardGrid>}
    {builder&&<Builder form={form} setForm={setForm} onClose={()=>setBuilder(false)} onSave={save}/>} {preview&&<Preview data={preview} onClose={()=>setPreview(null)}/>} 
  </div>;
}

function Builder({form,setForm,onClose,onSave}){const addCondition=()=>setForm({...form,conditions:[...form.conditions,{field_key:'CLIENT.status',operator:'EQUALS',expected_value:'ACTIVE'}]});const addAction=()=>setForm({...form,actions:[...form.actions,{action_type:'CREATE_TASK',configuration:{},confirmation_required:false}]});return <div className="fixed inset-0 z-50 overflow-y-auto bg-slate-950/55 p-3 sm:p-8"><section role="dialog" aria-modal="true" aria-labelledby="automation-builder-title" className="mx-auto max-w-3xl rounded-3xl bg-white p-5 sm:p-7"><div className="flex justify-between"><div><p className="text-xs font-bold uppercase tracking-widest text-blue-700">Guided builder</p><h2 id="automation-builder-title" className="text-2xl font-bold">New automation</h2></div><button aria-label="Close builder" onClick={onClose} className="h-11 w-11 rounded-xl border">×</button></div><div className="mt-6 space-y-5"><Field label="Automation name"><input value={form.name} onChange={e=>setForm({...form,name:e.target.value})} className="min-h-11 w-full rounded-xl border px-3"/></Field><Step label="WHEN"><select aria-label="Trigger" value={form.trigger_type} onChange={e=>setForm({...form,trigger_type:e.target.value})} className="min-h-11 w-full rounded-xl border px-3">{TRIGGERS.map(x=><option key={x} value={x}>{human(x)}</option>)}</select></Step><Step label="IF"><div className="space-y-3">{form.conditions.map((condition,index)=><div key={index} className="grid gap-2 sm:grid-cols-3"><select aria-label={`Condition field ${index+1}`} value={condition.field_key} onChange={e=>{const next=[...form.conditions];next[index]={...condition,field_key:e.target.value};setForm({...form,conditions:next})}} className="min-h-11 rounded-xl border px-2">{FIELDS.map(x=><option key={x} value={x}>{x}</option>)}</select><select aria-label={`Condition operator ${index+1}`} value={condition.operator} onChange={e=>{const next=[...form.conditions];next[index]={...condition,operator:e.target.value};setForm({...form,conditions:next})}} className="min-h-11 rounded-xl border px-2"><option>EQUALS</option><option>NOT_EQUALS</option><option>EXISTS</option></select><input aria-label={`Condition value ${index+1}`} value={condition.expected_value||''} onChange={e=>{const next=[...form.conditions];next[index]={...condition,expected_value:e.target.value};setForm({...form,conditions:next})}} className="min-h-11 rounded-xl border px-3"/></div>)}<button onClick={addCondition} className="min-h-11 rounded-xl border px-3 text-sm font-bold">Add condition</button></div></Step><Step label="THEN"><div className="space-y-3">{form.actions.map((action,index)=><select key={index} aria-label={`Action ${index+1}`} value={action.action_type} onChange={e=>{const next=[...form.actions];next[index]={...action,action_type:e.target.value};setForm({...form,actions:next})}} className="min-h-11 w-full rounded-xl border px-3">{ACTIONS.map(x=><option key={x} value={x}>{human(x)}</option>)}</select>)}<button onClick={addAction} className="min-h-11 rounded-xl border px-3 text-sm font-bold">Add action</button></div></Step><label className="flex min-h-11 items-center gap-3"><input type="checkbox" checked={form.requires_confirmation} onChange={e=>setForm({...form,requires_confirmation:e.target.checked})}/>Require practitioner confirmation</label><Field label="Cooldown minutes"><input type="number" min="1" value={form.cooldown_minutes} onChange={e=>setForm({...form,cooldown_minutes:e.target.value})} className="min-h-11 w-full rounded-xl border px-3"/></Field></div><div className="mt-7 flex justify-end gap-2"><button onClick={onClose} className="min-h-11 rounded-xl border px-4 font-bold">Cancel</button><button disabled={!form.name||!form.actions.length} onClick={onSave} className="min-h-11 rounded-xl bg-blue-700 px-4 font-bold text-white disabled:opacity-40">Save draft</button></div></section></div>}
function History({items}){return <section className="overflow-hidden rounded-2xl border bg-white"><div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left text-sm"><thead className="bg-slate-50"><tr>{['Automation','Client','Trigger','Status','Attempts','Timestamp'].map(x=><th key={x} className="p-4">{x}</th>)}</tr></thead><tbody>{items.map(item=><tr key={item.id} className="border-t"><td className="p-4 font-bold">{item.automation}</td><td className="p-4">{item.client_id||'—'}</td><td className="p-4">{human(item.trigger_type)}</td><td className="p-4">{human(item.status)}</td><td className="p-4">{item.attempt_count}</td><td className="p-4">{new Date(item.created_at).toLocaleString()}</td></tr>)}</tbody></table></div>{!items.length&&<Empty label="No automation executions yet"/>}</section>}
function Confirmation({items,decide}){return <div className="space-y-3">{items.map(item=><article key={item.id} className="flex flex-col gap-4 rounded-2xl border bg-white p-5 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-bold">{human(item.action_type)}</p><p className="text-sm text-slate-500">{item.automation} · client {item.client_id||'not supplied'}</p></div><div className="flex gap-2"><button onClick={()=>decide(item.id,'DISMISS')} className="min-h-11 rounded-xl border px-4 font-bold">Dismiss</button><button onClick={()=>decide(item.id,'APPROVE')} className="min-h-11 rounded-xl bg-emerald-700 px-4 font-bold text-white">Approve</button></div></article>)}{!items.length&&<Empty label="No actions waiting for confirmation"/>}</div>}
function Preview({data,onClose}){return <div className="fixed inset-0 z-50 grid place-items-center bg-slate-950/55 p-4"><section role="dialog" aria-modal="true" className="w-full max-w-lg rounded-3xl bg-white p-6"><div className="flex justify-between"><h2 className="text-xl font-bold">Dry-run preview</h2><button aria-label="Close preview" onClick={onClose} className="h-11 w-11 rounded-xl border">×</button></div><p className="mt-5 font-bold">Trigger matched: {data.trigger_matched?'YES':'NO'}</p><p className="mt-2 text-sm text-slate-600">No writes performed: {data.writes_performed===0?'YES':'NO'}</p><div className="mt-5 space-y-2">{data.actions?.map((action,index)=><p key={index} className="rounded-xl bg-slate-50 p-3 text-sm">{human(action.action_type)} · {action.would_execute?'Would run':'Would not run'}{action.confirmation_required?' · Confirmation required':''}</p>)}</div></section></div>}
function AutomationCard({title,subtitle,detail}){return <article className="rounded-2xl border bg-white p-5"><GitBranch className="text-blue-700"/><h3 className="mt-4 font-bold">{title}</h3><p className="mt-1 text-sm text-slate-500">{subtitle}</p><p className="mt-3 text-sm">{detail}</p></article>}
function CardGrid({children}){return <section className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{children}</section>}
function Empty({label}){return <div className="col-span-full rounded-2xl border border-dashed bg-white p-10 text-center"><ShieldCheck className="mx-auto text-slate-400"/><p className="mt-3 font-bold">{label}</p><p className="mt-1 text-sm text-slate-500">Confirmed empty from the automation service.</p></div>}
function StateCard({icon:Icon,title,copy,action,spin}){return <section className="rounded-3xl border bg-white p-10 text-center"><Icon className={`mx-auto text-blue-700 ${spin?'animate-spin':''}`}/><h2 className="mt-4 text-xl font-bold">{title}</h2><p className="mt-2 text-sm text-slate-500">{copy}</p>{action&&<button onClick={action} className="mt-5 min-h-11 rounded-xl bg-slate-950 px-4 font-bold text-white">Retry</button>}</section>}
function Step({label,children}){return <fieldset className="rounded-2xl border p-4"><legend className="px-2 text-sm font-black text-blue-700">{label}</legend>{children}</fieldset>}
function Field({label,children}){return <label className="block text-sm font-bold">{label}<span className="mt-2 block font-normal">{children}</span></label>}
